/* State for the translated DKC1 sound engine (sh/spceng_gen.c, generated by tools/audio/spc2x.py). */
#ifndef SPCENG_H
#define SPCENG_H
#include <stdint.h>

typedef struct spc_s {
    uint8_t ram[0x600];          /* engine variables, stack page, instrument table */
    const uint16_t *ctab;        /* song image: chunk index per 64 bytes of ARAM 0..$31FF (mkmusic.py) */
    const uint8_t *pool;         /* the shared 64-byte chunks */
    uint8_t dsp[128];            /* DSP register mirror */
    uint8_t port[4];
    uint8_t a, x, y, pad;
    void (*dspw)(struct spc_s *s, int reg, int val);
    void *user;
} spc_t;

enum { SPC_CODE_1071, SPC_CODE_064F, SPC_CODE_1173 };

static inline unsigned spc_rdx(spc_t *s, unsigned a)
{
    if (a < 0x600) return s->ram[a];
    if (a >= 0x3200) return 0;
    return s->pool[((uint32_t)s->ctab[a >> 6] << 6) | (a & 63)];
}

static inline void spc_wrx(spc_t *s, unsigned a, unsigned v)
{
    if (a < 0x600) s->ram[a] = (uint8_t)v;
}

static inline void spc_dspw(spc_t *s, unsigned v)
{
    unsigned r = s->ram[0xF2];
    if (r < 0x80) {
        s->dsp[r] = (uint8_t)v;
        if (s->dspw) s->dspw(s, r, v & 0xFF);
    }
}

void spc_exec(spc_t *s, int entry);
#endif
